package com.bitselect.catalog;
import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import org.springframework.jdbc.datasource.init.ResourceDatabasePopulator;import org.springframework.core.io.ClassPathResource;import java.util.UUID;import static org.junit.jupiter.api.Assertions.*;
class CatalogSearchTest {
 @Test void budgetAndAvailabilityAreSqlConstraints(){var source=new DriverManagerDataSource("jdbc:h2:mem:"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1","sa","");new ResourceDatabasePopulator(new ClassPathResource("db/migration/V1__commerce_schema.sql")).execute(source);var db=new JdbcTemplate(source);for(int i=1;i<=4;i++){db.update("INSERT INTO products(id,name,category,category_name,description,price_cents,original_price_cents,image_url,specifications,tags,enabled)VALUES(?,?,'audio','音频','说明',?,?, '/test.svg','{}','[]',?)",i,"无线耳机 "+i,i*9900,i*9900,i!=2);db.update("INSERT INTO inventory(product_id,stock,reserved)VALUES(?,?,0)",i,i==3?0:10);}var found=new CatalogProvider(db).searchProducts("预算300元的通勤耳机",30000,10);assertEquals(1,found.size());assertEquals(9900,found.getFirst().priceCents());assertEquals("耳机",ProductSearchTerm.normalize("通勤蓝牙耳机"));assertTrue(new CatalogProvider(db).searchProducts("耳机",5000,10).isEmpty());}
}
